    70	
    71	void FrameConsole::ReportMessageToClient(
    72	    mojom::blink::ConsoleMessageSource source,
    73	    mojom::blink::ConsoleMessageLevel level,
    74	    const String& message,
    75	    SourceLocation* location) {
    76	  if (source == mojom::blink::ConsoleMessageSource::kNetwork)
    77	    return;
    78	
    79	  String url = location->Url();
    80	  String stack_trace;
    81	  if (source == mojom::blink::ConsoleMessageSource::kConsoleApi) {
    82	    if (!frame_->GetPage())
    83	      return;
    84	    if (ShouldReportDetailedMessage(level, url)) {
    85	      SourceLocation* full_location =
    86	          SourceLocation::CaptureWithFullStackTrace();
    87	      if (!full_location->IsUnknown())
    88	        stack_trace = full_location->ToString();
    89	    }
    90	  } else {
    91	    if (!location->IsUnknown() && ShouldReportDetailedMessage(level, url)) {
    92	      stack_trace = location->ToString();
    93	    }
    94	  }
    95	
    96	  frame_->GetChromeClient().AddMessageToConsole(
    97	      frame_, source, level, message, location->LineNumber(), url, stack_trace);
    98	}
